// Do not rely on a locale-specific date string here. Some mobile browsers
// render `en-CA` as DD/MM/YYYY, which makes a saved server record fail the
// comparison with today's date and leaves the attendance card at 00:00:00.
function jakartaDate(value=new Date()){
  const parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(value);
  const values=Object.fromEntries(parts.filter(part=>part.type!=='literal').map(part=>[part.type,part.value]));
  return `${values.year}-${values.month}-${values.day}`;
}
const today=jakartaDate();
const todayDate=new Date(`${today}T00:00:00`);
