document.getElementById('attendanceDay').textContent=String(todayDate.getDate()).padStart(2,'0');
document.getElementById('attendanceMonth').textContent=todayDate.toLocaleDateString('id-ID',{month:'short'}).toUpperCase();
document.getElementById('attendancePeriod').textContent=todayDate.toLocaleDateString('id-ID',{month:'long',year:'numeric'});
