function resetCameraView(){const video=document.getElementById('selfieVideo'),canvas=document.getElementById('selfieCanvas'),placeholder=document.getElementById('cameraPlaceholder');video.hidden=false;canvas.hidden=true;placeholder.hidden=false;document.getElementById('cameraTitle').textContent='Menyiapkan kamera depan';document.getElementById('cameraMessage').textContent='Izinkan kamera agar wajah dapat dipotret.';document.getElementById('takeSelfie').textContent='Ambil';document.getElementById('takeSelfie').disabled=true}
