function ensureLocationRetry(){let button=document.getElementById('retryLocation');if(button)return button;button=document.createElement('button');button.type='button';button.id='retryLocation';button.textContent='Coba lokasi lagi';button.style.cssText='width:100%;margin-top:9px;border:0;background:#e7f6f5;color:#087d73;border-radius:8px;padding:9px;font-size:9px;font-weight:800';button.addEventListener('click',requestLocation);document.querySelector('.zone-action-card').append(button);return button}
function distanceMeters(a,b){const rad=value=>Number(value)*Math.PI/180,earth=6371000,lat1=rad(a.latitude),lat2=rad(b.latitude),deltaLat=lat2-lat1,deltaLng=rad(b.longitude)-rad(a.longitude),h=Math.sin(deltaLat/2)**2+Math.cos(lat1)*Math.cos(lat2)*Math.sin(deltaLng/2)**2;return earth*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}
function initializeAttendanceMap(){if(!window.L)return;if(!attendanceMap){attendanceMap=L.map('attendanceZoneMap',{zoomControl:true,attributionControl:true}).setView([-6.288,106.718],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(attendanceMap)}setTimeout(()=>attendanceMap.invalidateSize(),80)}
function updateAttendanceMap(){if(!attendanceMap)return;if(activeAttendanceZone){const zonePoint=[Number(activeAttendanceZone.latitude),Number(activeAttendanceZone.longitude)];if(attendanceZoneCircle)attendanceZoneCircle.remove();attendanceZoneCircle=L.circle(zonePoint,{radius:Number(activeAttendanceZone.radius_meters),color:'#1976d2',weight:2,fillColor:'#4b9cff',fillOpacity:.13}).addTo(attendanceMap).bindPopup(activeAttendanceZone.name)}if(capturedLocation){const userPoint=[capturedLocation.latitude,capturedLocation.longitude];if(attendanceUserMarker)attendanceUserMarker.remove();attendanceUserMarker=L.circleMarker(userPoint,{radius:9,color:'#fff',weight:3,fillColor:insideAttendanceZone?'#0aa190':'#d10b35',fillOpacity:1}).addTo(attendanceMap).bindPopup('Posisi Anda');if(attendanceZoneCircle){const bounds=attendanceZoneCircle.getBounds();bounds.extend(userPoint);attendanceMap.fitBounds(bounds,{padding:[28,28],maxZoom:16})}else attendanceMap.setView(userPoint,16)}else if(attendanceZoneCircle)attendanceMap.fitBounds(attendanceZoneCircle.getBounds(),{padding:[24,24]})}
function applyAttendanceZone(){const statusEl=document.getElementById('locationStatus'),coords=document.getElementById('locationCoordinates'),accuracy=document.getElementById('locationAccuracy'),checkInButton=document.getElementById('zoneCheckIn'),checkOutButton=document.getElementById('zoneCheckOut');if(!capturedLocation){updateAttendanceMap();return}if(!activeAttendanceZone){insideAttendanceZone=false;statusEl.textContent='Zona absensi belum diatur';coords.textContent='Hubungi administrator untuk mengatur zona';accuracy.textContent='—';checkInButton.disabled=true;checkOutButton.disabled=true;updateAttendanceMap();return}const distance=Math.round(distanceMeters(capturedLocation,activeAttendanceZone)),radius=Math.round(activeAttendanceZone.radius_meters);insideAttendanceZone=distance<=radius;capturedLocation.zoneId=activeAttendanceZone.id;capturedLocation.zoneName=activeAttendanceZone.name;capturedLocation.zoneDistanceMeters=distance;document.getElementById('locationData').value=JSON.stringify(capturedLocation);document.getElementById('zoneDistance').textContent=distance>=1000?`${(distance/1000).toLocaleString('id-ID',{maximumFractionDigits:2})} KM`:`${distance} M`;statusEl.textContent=insideAttendanceZone?'Anda berada di dalam zona':'Anda masih berada di luar zona';coords.textContent=`Akurasi GPS ±${capturedLocation.accuracy} m`;accuracy.textContent=insideAttendanceZone?'✓ Sesuai':'Di luar';checkInButton.disabled=!insideAttendanceZone||attendanceMode!=='checkin';checkOutButton.disabled=!insideAttendanceZone||attendanceMode!=='checkout';updateAttendanceMap()}
async function loadAttendanceZone(){if(!window.hmaSupabase)return;const {data,error}=await window.hmaSupabase.from('attendance_zones').select('id,name,latitude,longitude,radius_meters').eq('is_active',true).order('created_at',{ascending:true}).limit(1).maybeSingle();activeAttendanceZone=error?null:data||null;document.getElementById('zoneName').textContent=activeAttendanceZone?.name||'Zona belum tersedia';document.getElementById('zoneRadius').textContent=activeAttendanceZone?`${Math.round(activeAttendanceZone.radius_meters).toLocaleString('id-ID')} M`:'—';document.getElementById('zoneCoordinates').textContent=activeAttendanceZone?`${Number(activeAttendanceZone.latitude).toFixed(5)}, ${Number(activeAttendanceZone.longitude).toFixed(5)}`:'Hubungi administrator';applyAttendanceZone()}
function requestLocation(){const statusEl=document.getElementById('locationStatus'),coords=document.getElementById('locationCoordinates'),accuracy=document.getElementById('locationAccuracy'),retry=ensureLocationRetry();statusEl.textContent='Memeriksa posisi perangkat…';coords.textContent='Posisi dipakai untuk verifikasi zona';accuracy.textContent='…';retry.hidden=true;document.getElementById('zoneCheckIn').disabled=true;document.getElementById('zoneCheckOut').disabled=true;if(locationRetryTimer){clearTimeout(locationRetryTimer);locationRetryTimer=null}if(locationWatchId!==null){navigator.geolocation?.clearWatch(locationWatchId);locationWatchId=null}if(!navigator.geolocation){statusEl.textContent='Lokasi tidak didukung';coords.textContent='Gunakan perangkat dengan layanan lokasi';accuracy.textContent='—';retry.hidden=false;return}let usingFallback=false;const success=pos=>{capturedLocation={latitude:pos.coords.latitude,longitude:pos.coords.longitude,accuracy:Math.round(pos.coords.accuracy),capturedAt:new Date().toISOString()};document.getElementById('locationData').value=JSON.stringify(capturedLocation);retry.hidden=true;applyAttendanceZone();if(locationWatchId!==null){navigator.geolocation.clearWatch(locationWatchId);locationWatchId=null}};const startWatch=options=>{locationWatchId=navigator.geolocation.watchPosition(success,error=>{if(!usingFallback&&error?.code!==1){usingFallback=true;if(locationWatchId!==null)navigator.geolocation.clearWatch(locationWatchId);startWatch({enableHighAccuracy:false,timeout:20000,maximumAge:120000});return}if(locationWatchId!==null){navigator.geolocation.clearWatch(locationWatchId);locationWatchId=null}const denied=error?.code===1;statusEl.textContent=denied?'Izin lokasi belum diberikan':'Memeriksa lokasi lagi';coords.textContent=denied?'Izinkan lokasi pada browser untuk memverifikasi zona.':'Sinyal lokasi belum tersedia; sistem mencoba kembali otomatis.';accuracy.textContent=denied?'Izin':'Menunggu';retry.hidden=false;if(!denied)locationRetryTimer=setTimeout(requestLocation,4000)},options)};startWatch({enableHighAccuracy:true,timeout:20000,maximumAge:0})}
function updateAttendanceClock(){let now;try{now=new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date())}catch{now=new Date().toLocaleTimeString('id-ID',{hour12:false})}const trusted=document.getElementById('trustedTime'),clock=document.getElementById('shiftClock'),homeClock=document.getElementById('homeLiveClock'),todays=activeAttendance().find(x=>x.date===today);if(trusted){try{trusted.textContent=`${deviceTime()} · jam final menggunakan server`}catch{trusted.textContent=`${now} WIB · jam final menggunakan server`}}if(clock)clock.textContent=`Jam berjalan ${now} WIB · Shift Pagi 08.00–16.00`;if(homeClock)homeClock.textContent=`${now} WIB · waktu perangkat`;const arrival=document.getElementById('zoneArrivalClock'),departure=document.getElementById('zoneDepartureClock');if(arrival)arrival.textContent=todays?.checkInTime||now;if(departure)departure.textContent=todays?.checkOutTime||now}
function openAttendance(){if(!currentUser){showToast('Silakan masuk dengan akun karyawan terlebih dahulu.');return}const todays=activeAttendance().find(x=>x.date===today);if(todays?.checkOutTime){showToast('Absensi hari ini sudah lengkap.');return}attendanceMode=todays?'checkout':'checkin';capturedLocation=null;insideAttendanceZone=false;attendanceSaving=false;document.getElementById('attendanceForm').reset();document.getElementById('selfieData').value='';document.getElementById('locationData').value='';document.getElementById('attendanceZoneStep').hidden=false;document.getElementById('attendanceCameraStep').hidden=true;document.getElementById('attendanceProcessing').hidden=true;document.getElementById('zoneDistance').textContent='—';document.getElementById('zoneDate').textContent=todayDate.toLocaleDateString('id-ID',{day:'2-digit',month:'2-digit'});document.getElementById('attendanceFlowLabel').textContent=attendanceMode==='checkout'?'CHECK-OUT SHIFT PAGI':'CHECK-IN SHIFT PAGI';document.getElementById('attendanceFlowTitle').textContent=attendanceMode==='checkout'?'Validasi zona pulang':'Validasi zona datang';attendanceDialog.showModal();initializeAttendanceMap();updateAttendanceClock();attendanceClock=setInterval(updateAttendanceClock,1000);loadAttendanceZone();requestLocation()}
