async function captureSelfieAndSave(){const video=document.getElementById('selfieVideo'),canvas=document.getElementById('selfieCanvas');if(!video.videoWidth){showToast('Kamera belum siap. Gunakan pilihan Kamera HP bila perlu.');return}canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);setCapturedSelfie(canvas.toDataURL('image/jpeg',.82));document.getElementById('takeSelfie').disabled=true;await saveAttendanceAutomatically()}
function captureSelfieFile(file){if(!file||attendanceSaving)return;const image=new Image(),url=URL.createObjectURL(file);image.onload=async()=>{const canvas=document.getElementById('selfieCanvas'),max=960,scale=Math.min(1,max/Math.max(image.width,image.height));canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);setCapturedSelfie(canvas.toDataURL('image/jpeg',.82));await saveAttendanceAutomatically()};image.onerror=()=>{URL.revokeObjectURL(url);showToast('Foto tidak dapat dibaca. Silakan ambil ulang.')};image.src=url}
