function dataUrlToBlob(dataUrl){const [meta,raw]=dataUrl.split(',');const bytes=Uint8Array.from(atob(raw),c=>c.charCodeAt(0));return new Blob([bytes],{type:meta.match(/:(.*?);/)[1]})}
async function saveAttendanceToSupabase(selfie,location){
  if(!window.hmaSupabase) throw new Error('Koneksi server absensi belum tersedia.');
  const {data:{user}}=await window.hmaSupabase.auth.getUser();
  if(!user) throw new Error('Sesi karyawan berakhir. Silakan masuk kembali.');
  const suffix=crypto.randomUUID();
  const path=`${user.id}/${today}/${attendanceMode}-${suffix}.jpg`;
  const upload=await window.hmaSupabase.storage.from('attendance-selfies').upload(path,dataUrlToBlob(selfie),{contentType:'image/jpeg',upsert:false});
  if(upload.error) throw upload.error;
  const record=attendanceMode==='checkout'?await window.hmaSupabase.rpc('check_out_attendance',{p_latitude:location.latitude,p_longitude:location.longitude,p_accuracy_meters:location.accuracy,p_selfie_path:path,p_client_time:new Date().toISOString()}):await window.hmaSupabase.rpc('check_in_attendance',{p_latitude:location.latitude,p_longitude:location.longitude,p_accuracy_meters:location.accuracy,p_selfie_path:path,p_client_time:new Date().toISOString()});
  if(record.error){await window.hmaSupabase.storage.from('attendance-selfies').remove([path]);throw record.error}
  return record.data||true;
}
function formatShiftTime(value,fallback){return value?String(value).slice(0,5).replace(':','.') : fallback}
function mapAttendanceRow(row){return {employee:currentEmployee,date:String(row.check_in_date),checkInTime:formatTime(row.check_in_at),checkOutTime:formatTime(row.check_out_at),status:row.check_out_at?'Selesai':'Hadir',lateMinutes:Number(row.late_minutes||0),earlyLeaveMinutes:Number(row.early_leave_minutes||0),shiftName:row.shift_name||'Shift Pagi',shiftStart:formatShiftTime(row.shift_start_time,'08.00'),shiftEnd:formatShiftTime(row.shift_end_time,'16.00'),checkInLocation:{latitude:row.latitude,longitude:row.longitude,accuracy:row.accuracy_meters},location:{latitude:row.latitude,longitude:row.longitude,accuracy:row.accuracy_meters},synced:true}}
async function loadAttendanceFromSupabase(){if(!currentUser||!window.hmaSupabase)return false;let {data,error}=await window.hmaSupabase.rpc('my_attendance_records');if(error){console.warn('Attendance RPC refresh failed:',error.message);({data,error}=await window.hmaSupabase.from('attendance').select('check_in_date,check_in_at,check_out_at,latitude,longitude,accuracy_meters,selfie_path,verification_status,shift_name,shift_start_time,shift_end_time,late_minutes,early_leave_minutes').eq('employee_id',currentUser.id).order('check_in_date',{ascending:false}))}if(error){console.warn('Attendance refresh failed:',error.message);return false}attendanceLoadedFromServer=true;remoteAttendance=(data||[]).map(mapAttendanceRow);refreshAttendance();return true}
async function saveAttendanceAutomatically(){const selfie=document.getElementById('selfieData').value,location=document.getElementById('locationData').value;if(attendanceSaving)return;if(!selfie||!location||!insideAttendanceZone){const message=!location?'Posisi perangkat belum terbaca.':!insideAttendanceZone?'Anda berada di luar zona absensi.':'Foto selfie belum tersedia.';attendanceFeedback(message);showToast(message);return}attendanceSaving=true;const parsedLocation=JSON.parse(location),mode=attendanceMode;attendanceFeedback(`Mengirim foto dan mencatat jam ${mode==='checkout'?'pulang':'datang'}…`,'success');try{const result=await saveAttendanceToSupabase(selfie,parsedLocation);const refreshed=await loadAttendanceFromSupabase();let saved=activeAttendance().find(x=>x.date===today);if(!saved&&result&&typeof result==='object'){attendanceLoadedFromServer=true;const serverRow=mapAttendanceRow(result);remoteAttendance=[serverRow,...remoteAttendance.filter(row=>row.date!==serverRow.date)];refreshAttendance();saved=serverRow}if(!saved)throw new Error(refreshed?'Rekaman absensi belum ditemukan. Muat ulang lalu coba lagi.':'Absensi sudah diterima server, tetapi tampilan belum dapat disegarkan.');const late=Number(saved.lateMinutes||0),message=mode==='checkout'?`Check-out berhasil pada ${saved.checkOutTime||'waktu server'}.`:`Check-in berhasil pada ${saved.checkInTime||'waktu server'}. ${late>0?`Anda terlambat ${late} menit.`:'Anda tepat waktu.'}`;attendanceFeedback(message,'success');showToast(message);setTimeout(closeAttendance,1100)}catch(error){const raw=error?.message||'coba lagi',message=raw.includes('duplicate')?'Anda sudah check-in hari ini.':raw.includes('di luar zona')?raw:'Absensi belum tersimpan: '+raw;attendanceFeedback(`${message} Ambil foto ulang untuk mencoba kembali.`);showToast(message);document.getElementById('selfieFile').value='';document.getElementById('selfieCanvas').hidden=true;document.getElementById('cameraPlaceholder').hidden=false;startCamera()}finally{attendanceSaving=false}}
