async function applyEmployeeSession(){if(!window.hmaSupabase){showToast('Koneksi backend belum tersedia.');return}const {data:{user}}=await window.hmaSupabase.auth.getUser();if(!user){currentUser=null;currentProfile=null;currentEmployee='';remoteAttendance=[];attendanceLoadedFromServer=false;document.body.classList.remove('employee-authenticated');if(!window.location.hash)window.location.replace('./');return}const {data:profile,error}=await window.hmaSupabase.from('profiles').select('employee_code,full_name,role,position,phone,avatar_path').eq('id',user.id).single();if(error||!profile){await window.hmaSupabase.auth.signOut();showToast('Profil karyawan tidak ditemukan. Hubungi administrator.');return}if(profile.role!=='employee'){window.location.replace('./');return}currentUser=user;currentProfile=profile;currentEmployee=profile.full_name;attendanceLoadedFromServer=false;const initials=currentEmployee.split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase()||'HM';await loadProfileAvatar(profile.avatar_path,initials);document.getElementById('employeeProfileName').textContent=currentEmployee;document.getElementById('homeEmployeeName').textContent=currentEmployee;document.getElementById('employeeProfileRole').textContent=`${profile.position||'Karyawan'} · HMA`;document.getElementById('homeEmployeeIdentity').textContent=`${profile.employee_code||'HMA'} · ${profile.position||'Karyawan'}`;document.body.classList.add('employee-authenticated');updateEmployeeGreeting();refreshAttendance();await loadAttendanceFromSupabase();await loadEmployeeRequests();}
document.getElementById('employeeLoginForm').addEventListener('submit',async e=>{e.preventDefault();if(!window.hmaSupabase){showToast('Koneksi backend belum tersedia.');return}const submit=e.currentTarget.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='Memeriksa akun…';try{const employeeId=document.getElementById('employeeLoginId').value.trim().toUpperCase();if(!/^HMA\d{3,}$/.test(employeeId))throw new Error('Format ID karyawan tidak valid. Contoh: HMA001');const {error}=await window.hmaSupabase.auth.signInWithPassword({email:`${employeeId.toLowerCase()}@accounts.hma.internal`,password:document.getElementById('employeeLoginPassword').value});if(error)throw new Error(error.message==='Invalid login credentials'?'ID karyawan atau kata sandi tidak sesuai.':error.message);await applyEmployeeSession();if(!currentUser)throw new Error('Akun ini belum memiliki akses karyawan.');showToast('Login karyawan berhasil.')}catch(error){showToast(error.message||'Login gagal.')}finally{submit.disabled=false;submit.textContent='Masuk ke aplikasi'}});
