async function loadEmployeeRequests(){if(!currentUser||!window.hmaSupabase)return;const table=requestMode==='loan'?'employee_cash_advances':'employee_leave_requests';const {data,error}=await window.hmaSupabase.from(table).select('*').eq('employee_id',currentUser.id).order('created_at',{ascending:false});const list=document.getElementById('taskList');if(error){list.innerHTML='<article class="task-card"><h2>Riwayat belum tersedia</h2><p>Silakan coba kembali sesaat lagi.</p></article>';return}const rows=data||[];document.getElementById('requestHistoryMeta').textContent=rows.length?`${rows.length} pengajuan tercatat`:'Belum ada pengajuan';list.innerHTML=rows.length?rows.map(row=>{const statusText=requestStatusLabel[row.status]||row.status;const title=requestMode==='loan'?`Kasbon ${formatRupiah(row.amount)}`:`${String(row.request_type).toUpperCase()} · ${new Date(`${row.start_date}T00:00:00`).toLocaleDateString('id-ID',{day:'2-digit',month:'short'})}`;const detail=requestMode==='loan'?row.note:`${new Date(`${row.start_date}T00:00:00`).toLocaleDateString('id-ID')} – ${new Date(`${row.end_date}T00:00:00`).toLocaleDateString('id-ID')}${row.note?` · ${row.note}`:''}`;return `<article class="task-card"><header>${status(statusText,row.status==='approved'?'active-status':'pending')}<small>${new Date(row.created_at).toLocaleDateString('id-ID')}</small></header><h2>${title}</h2><p>${detail}</p></article>`}).join(''):`<article class="task-card"><h2>Belum ada pengajuan</h2><p>${requestMode==='loan'?'Pengajuan kasbon':'Izin atau cuti'} Anda akan muncul di sini.</p></article>`}
