async function openEmployeeFuel(){if(!currentUser){showToast('Silakan masuk dengan akun karyawan terlebih dahulu.');return}const select=document.getElementById('employeeFuelVehicle');select.innerHTML='<option value="">Memuat armada…</option>';document.getElementById('employeeFuelForm').reset();formatRupiahField(document.getElementById('employeeFuelPrice'));try{const {data,error}=await window.hmaSupabase.from('vehicles').select('id,plate_no,model,current_odometer').in('status',['active','maintenance']).order('plate_no');if(error)throw error;select.innerHTML='<option value="">Pilih kendaraan</option>'+(data||[]).map(vehicle=>`<option value="${vehicle.id}" data-odometer="${vehicle.current_odometer}">${vehicle.plate_no}${vehicle.model?` · ${vehicle.model}`:''}</option>`).join('');if(!(data||[]).length)showToast('Belum ada armada yang dapat dipilih.');fuelDialog.showModal()}catch(error){showToast(error.message||'Daftar armada belum dapat dimuat.')}}
function fuelEfficiency(type){return String(type||'').trim().toLowerCase()==='solar'?7:9}
function updateEmployeeFuelStandard(){const efficiency=fuelEfficiency(document.getElementById('employeeFuelType')?.value),note=document.querySelector('#employeeFuelEstimate + small');if(note)note.textContent=`Standar perusahaan: 1 liter untuk ${efficiency} KM.`;calculateEmployeeFuel()}
function calculateEmployeeFuel(){const previous=Number(document.getElementById('employeeFuelPrevious').value),current=Number(document.getElementById('employeeFuelCurrent').value),label=document.getElementById('employeeFuelEstimate'),efficiency=fuelEfficiency(document.getElementById('employeeFuelType')?.value);if(current>previous){const distance=current-previous;label.textContent=`Jarak ${distance.toLocaleString('id-ID')} KM · estimasi ${(distance/efficiency).toLocaleString('id-ID',{maximumFractionDigits:2})} L`}else label.textContent='Masukkan KM dengan benar untuk melihat estimasi'}
document.querySelectorAll('[data-open="fuel"]').forEach(x=>x.addEventListener('click',openEmployeeFuel));document.querySelectorAll('[data-close="fuelDialog"]').forEach(x=>x.addEventListener('click',()=>fuelDialog.close()));
document.getElementById('employeeFuelVehicle').addEventListener('change',e=>{const option=e.target.selectedOptions[0];if(option?.dataset.odometer)document.getElementById('employeeFuelPrevious').value=option.dataset.odometer;calculateEmployeeFuel()});['employeeFuelPrevious','employeeFuelCurrent'].forEach(id=>document.getElementById(id).addEventListener('input',calculateEmployeeFuel));document.getElementById('employeeFuelType').addEventListener('change',updateEmployeeFuelStandard);
document.getElementById('employeeFuelPrice').addEventListener('input',event=>formatRupiahField(event.currentTarget));document.getElementById('employeeFuelForm').noValidate=true;document.getElementById('employeeFuelForm').addEventListener('submit',async e=>{e.preventDefault();if(!ensureEmployeeSession())return;const submit=e.currentTarget.querySelector('[type="submit"]'),vehicleId=document.getElementById('employeeFuelVehicle').value,previous=Number(document.getElementById('employeeFuelPrevious').value),current=Number(document.getElementById('employeeFuelCurrent').value),liters=Number(document.getElementById('employeeFuelLiters').value),price=parseRupiahInput(document.getElementById('employeeFuelPrice').value);if(!vehicleId){showToast('Pilih kendaraan terlebih dahulu.');return}if(!Number.isFinite(previous)||!Number.isFinite(current)||previous<0||current<0){showToast('Masukkan KM sebelumnya dan KM saat isi.');return}if(current<previous){showToast('KM saat isi harus lebih besar atau sama dengan KM sebelumnya.');return}if(!Number.isFinite(liters)||liters<=0){showToast('Jumlah liter BBM harus lebih dari 0.');return}if(!Number.isFinite(price)||price<=0){showToast('Harga per liter BBM harus lebih dari 0.');return}submit.disabled=true;submit.textContent='Mengirim…';try{const {error}=await window.hmaSupabase.from('fuel_logs').insert({vehicle_id:vehicleId,employee_id:currentUser.id,previous_odometer:previous,current_odometer:current,liters,price_per_liter:price,fuel_type:document.getElementById('employeeFuelType').value});if(error)throw error;fuelDialog.close();showToast('Pengisian BBM berhasil dikirim untuk ditinjau admin.')}catch(error){const message=error.code==='42501'?'Akses input BBM belum aktif untuk akun ini.':error.code==='23514'?'Data KM atau BBM tidak sesuai aturan. Periksa kembali inputnya.':(error.message||'Pengisian BBM belum tersimpan.');showToast(message)}finally{submit.disabled=false;submit.textContent='Kirim pengisian'}});
document.querySelector('.logout').addEventListener('click',async()=>{closeAttendance();profileDialogs.forEach(id=>{const profileDialog=document.getElementById(id);if(profileDialog?.open)profileDialog.close()});if(window.hmaSupabase)await window.hmaSupabase.auth.signOut();currentUser=null;currentProfile=null;currentEmployee='';document.body.classList.remove('employee-authenticated');window.location.replace('./')});
if(window.hmaSupabase)window.hmaSupabase.auth.onAuthStateChange(()=>setTimeout(applyEmployeeSession,0));
applyEmployeeSession();
